  <h1 class="pad">Proven <span class="r">RESULTS</span> for <span class="r">WILLOWMERE</span> Families</h1>
  <div class="g g1"></div>
  <div class="photo"><img src="photo.jpg" alt=""></div>
  <div class="g g2"></div>
  <div class="cands pad">
    <div class="cand"><div class="nm">Dana Levi</div><div class="ro">Mayor</div></div>
    <div class="cand"><div class="nm">Omar Haddad</div><div class="ro">Council</div></div>
    <div class="cand"><div class="nm">Ruth Cohen</div><div class="ro">Council</div></div>
  </div>
  <div class="g g3"></div>
  <div class="cta"><img src="mail.svg" alt=""><span>VOTE BY MAIL</span></div>
  <div class="g g4"></div>
  <div class="steps pad">
    <div class="stepwrap">
      <div class="step"><img src="check.svg" alt=""><span>Request your ballot by October 20</span></div>
      <div class="step"><img src="check.svg" alt=""><span>Fill it out at home</span></div>
      <div class="step"><img src="check.svg" alt=""><span>Mail it back by November 3</span></div>
    </div>
  </div>
  <div class="g g5"></div>
  <div class="foot pad">Paid for by Willowmere Forward &middot; willowmereforward.org</div>
</div>
</body></html>`;

const sizes = {portrait: 1, wide: 0.85, sky: 0.28};
for (const [name, s] of Object.entries(sizes)) {
  fs.writeFileSync(`${name}.html`, tpl(s));
}
console.log('written');

